"""Execute permission choice view and runtime permission policy, no real grants."""
from pathlib import Path
import runpy,subprocess,tempfile,re
stubs=dict(runpy.run_path('tests/test_setup_language.py')['stubs'])
stubs.pop('io/tvos/LanguageTest.java')
stubs['android/view/View.java']=stubs['android/view/View.java'].replace('public int posts;', 'public String description;public int posts;').replace('public void setContentDescription(String s){}', 'public void setContentDescription(String s){description=s;}')
source=Path('app/src/io/tvos/SetupPermissionsView.java').read_text()
ids=sorted(set(re.findall(r'R.string.(settings_\w+)',source)))
stubs['io/tvos/R.java']='package io.tvos;class R {static class string {'+''.join('static final int '+name+'='+str(i+1)+';' for i,name in enumerate(ids))+'}}'
stubs['io/tvos/AppStrings.java']='package io.tvos;class AppStrings {static String get(int id){return "permission "+id;}}'
stubs['android/graphics/Path.java']=stubs['android/graphics/Path.java'].replace('enum Direction {CW}','enum Direction {CW,CCW}')
stubs['android/graphics/Paint.java']=stubs['android/graphics/Paint.java'].replace('enum Align {CENTER}','enum Align {CENTER,LEFT}')
stubs['io/tvos/PermissionTest.java']='''package io.tvos;import android.content.Context;import android.graphics.Canvas;import android.view.KeyEvent;import io.tvos.setup.SetupPermissionPlan;import java.util.*;class PermissionTest {static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[] args){check(SetupPermissionPlan.runtime(28,true,false,true).length==0,"skip granted and unavailable TV access");String[] modern=SetupPermissionPlan.runtime(33,false,true,false);check(Arrays.asList(modern).contains("android.permission.ACCESS_COARSE_LOCATION")&&Arrays.asList(modern).contains("android.permission.ACCESS_FINE_LOCATION")&&Arrays.asList(modern).contains("android.permission.READ_TV_LISTINGS")&&modern.length==3,"modern location pair and denied dangerous TV access");check(SetupPermissionPlan.runtime(28,false,true,false).length==2,"legacy requests fine plus TV only");check(SetupPermissionPlan.runtime(33,true,true,true).length==0,"already granted no prompt");int[] allow={0},deny={0};Context.reduced=true;SetupPermissionsView v=new SetupPermissionsView(new Context(),()->allow[0]++,()->deny[0]++);Canvas c=new Canvas();v.onDraw(c);check(v.description.contains("permission "+R.string.settings_setup_location_line2)&&v.description.contains("permission "+R.string.settings_setup_remote_line2)&&v.description.contains("permission "+R.string.settings_setup_history_line2),"screen reader receives all access explanations");check(c.paths==3&&c.capsules>=4,"three native card icons and focused allow capsule");v.onKeyDown(20,new KeyEvent(0,false));v.onKeyUp(23,new KeyEvent(0,false));check(deny[0]==0,"orphan release ignored");v.onKeyDown(23,new KeyEvent(0,false));v.onWindowFocusChanged(false);v.onKeyUp(23,new KeyEvent(0,false));check(deny[0]==0,"focus loss cancels");v.onKeyDown(23,new KeyEvent(0,false));v.onKeyUp(23,new KeyEvent(0,false));v.onKeyDown(23,new KeyEvent(0,false));v.onKeyUp(23,new KeyEvent(0,false));check(deny[0]==1&&allow[0]==0,"decline once without grant callback");SetupPermissionsView yes=new SetupPermissionsView(new Context(),()->allow[0]++,()->deny[0]++);yes.onKeyDown(23,new KeyEvent(0,false));yes.onKeyUp(23,new KeyEvent(0,false));check(allow[0]==1,"allow explicitly starts platform flow");yes.onDetachedFromWindow();System.out.println("PASS: actual permission view, optional consent/decline and SDK/grant runtime policy");}}'''
with tempfile.TemporaryDirectory() as tmp:
 root=Path(tmp)
 for name,code in stubs.items():
  p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(code)
 for name in ['SetupPermissionsView.java','setup/SetupPermissionPlan.java','setup/SetupArtwork.java','Spring.java']:
  p=root/'io/tvos'/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text((Path('app/src/io/tvos')/name).read_text())
 subprocess.run(['java','com.sun.tools.javac.Main','--release','8','-Xlint:all,-options','-Werror','-d',tmp,*map(str,root.rglob('*.java'))],check=True)
 subprocess.run(['java','-cp',tmp,'io.tvos.PermissionTest'],check=True,timeout=15)
